import { useEffect, useRef } from 'react';
import type { StyleProp, ViewStyle } from 'react-native';
import LottieView from 'lottie-react-native';
import { prefersReducedMotion } from './ui';

// Same original Lottie files as the web app (generated by shared/lottie/build.mjs).
const FILES = {
  thoranam: require('../../assets/lottie/thoranam.json'),
  lamp: require('../../assets/lottie/lamp.json'),
  celebrate: require('../../assets/lottie/celebrate.json'),
  kolam: require('../../assets/lottie/kolam.json'),
  'petals-drift': require('../../assets/lottie/petals-drift.json'),
};

export type AnimName = keyof typeof FILES;

export function Anim({
  name,
  loop = true,
  style,
  stillFrame = 0,
  resizeMode = 'contain',
  onFinish,
}: {
  name: AnimName;
  loop?: boolean;
  style?: StyleProp<ViewStyle>;
  stillFrame?: number;
  resizeMode?: 'cover' | 'contain' | 'center';
  onFinish?: () => void;
}) {
  const ref = useRef<LottieView>(null);
  const reduce = prefersReducedMotion();
  useEffect(() => {
    if (!reduce) return;
    ref.current?.play(stillFrame, stillFrame);
    // No playback means no "finished" event — send it ourselves so overlays don't get stuck.
    if (onFinish) {
      const t = setTimeout(() => onFinish(), 1200);
      return () => clearTimeout(t);
    }
  }, [reduce, stillFrame, onFinish]);
  return (
    <LottieView
      ref={ref}
      source={FILES[name]}
      autoPlay={!reduce}
      loop={reduce ? false : loop}
      resizeMode={resizeMode}
      onAnimationFinish={onFinish}
      style={style}
    />
  );
}
